class CharacterProfile extends DataClass
    implements Insertable<CharacterProfile> {
  final String id;
  final String name;
  final String role;
  final String gender;

  /// 可用于显示、检索和同一人物识别的曾用名、称号与昵称。
  final List<String> aliases;

  /// 供角色列表筛选与分组使用的自由标签，不承担剧情关系语义。
  final List<String> tags;

  /// 人物小传：记录人物设定、动机、关系和弧光等完整信息。
  /// 这是人物的「档案」，通常在创作初期设定，后续较少改动。
  final String biography;

  /// 人物外观：体貌、发型发色、眼睛、服饰等稳定视觉特征。
  final String appearance;

  /// 人物描述：声线、动作习惯、可观察气质和公众印象。
  /// 这是相对稳定的人物档案，不记录临时位置、伤势和知识状态。
  final String description;

  /// 人物在最新剧情节点的位置、伤势、物品、能力、情绪、目标与知识边界。
  final String currentState;

  /// 角色头像图片资产
  final String? avatarAssetId;

  /// 角色照片集，保存图片资产和名称。
  final List<SubjectPhoto>? photos;

  /// 角色跨集共用的参考音频及名称。
  final List<CharacterVoice>? voices;

  /// 角色身份/称号
  final String identity;

  /// 角色年龄
  final String age;

  /// 角色动机
  final String motivation;

  /// 人物弧光
  final String arc;

  /// 角色性格描述：性格特质、行为模式等
  final String personality;

  /// 带情境的人物行为倾向，每项为 tag + context。
  final List<CharacterBehaviorTag> behaviorTags;

  /// 角色首次出场章节 ID
  final String? firstAppearChapterId;
  final int sortOrder;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime deletedAt;
  const CharacterProfile({
    required this.id,
    required this.name,
    required this.role,
    required this.gender,
    required this.aliases,
    required this.tags,
    required this.biography,
    required this.appearance,
    required this.description,
    required this.currentState,
    this.avatarAssetId,
    this.photos,
    this.voices,
    required this.identity,
    required this.age,
    required this.motivation,
    required this.arc,
    required this.personality,
    required this.behaviorTags,
    this.firstAppearChapterId,
    required this.sortOrder,
    required this.createdAt,
    required this.updatedAt,
    required this.deletedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['name'] = Variable<String>(name);
    map['role'] = Variable<String>(role);
    map['gender'] = Variable<String>(gender);
    {
      map['aliases'] = Variable<String>(
        $CharacterProfilesTable.$converteraliases.toSql(aliases),
      );
    }
    {
      map['tags'] = Variable<String>(
        $CharacterProfilesTable.$convertertags.toSql(tags),
      );
    }
    map['biography'] = Variable<String>(biography);
    map['appearance'] = Variable<String>(appearance);
    map['description'] = Variable<String>(description);
    map['current_state'] = Variable<String>(currentState);
    if (!nullToAbsent || avatarAssetId != null) {
      map['avatar_asset_id'] = Variable<String>(avatarAssetId);
    }
    if (!nullToAbsent || photos != null) {
      map['photos'] = Variable<String>(
        $CharacterProfilesTable.$converterphotosn.toSql(photos),
      );
    }
    if (!nullToAbsent || voices != null) {
      map['voices'] = Variable<String>(
        $CharacterProfilesTable.$convertervoicesn.toSql(voices),
      );
    }
    map['identity'] = Variable<String>(identity);
    map['age'] = Variable<String>(age);
    map['motivation'] = Variable<String>(motivation);
    map['arc'] = Variable<String>(arc);
    map['personality'] = Variable<String>(personality);
    {
      map['behavior_tags'] = Variable<String>(
        $CharacterProfilesTable.$converterbehaviorTags.toSql(behaviorTags),
      );
    }
    if (!nullToAbsent || firstAppearChapterId != null) {
      map['first_appear_chapter_id'] = Variable<String>(firstAppearChapterId);
    }
    map['sort_order'] = Variable<int>(sortOrder);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['deleted_at'] = Variable<DateTime>(deletedAt);
    return map;
  }

  CharacterProfilesCompanion toCompanion(bool nullToAbsent) {
    return CharacterProfilesCompanion(
      id: Value(id),
      name: Value(name),
      role: Value(role),
      gender: Value(gender),
      aliases: Value(aliases),
      tags: Value(tags),
      biography: Value(biography),
      appearance: Value(appearance),
      description: Value(description),
      currentState: Value(currentState),
      avatarAssetId: avatarAssetId == null && nullToAbsent
          ? const Value.absent()
          : Value(avatarAssetId),
      photos: photos == null && nullToAbsent
          ? const Value.absent()
          : Value(photos),
      voices: voices == null && nullToAbsent
          ? const Value.absent()
          : Value(voices),
      identity: Value(identity),
      age: Value(age),
      motivation: Value(motivation),
      arc: Value(arc),
      personality: Value(personality),
      behaviorTags: Value(behaviorTags),
      firstAppearChapterId: firstAppearChapterId == null && nullToAbsent
          ? const Value.absent()
          : Value(firstAppearChapterId),
      sortOrder: Value(sortOrder),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: Value(deletedAt),
    );
  }

  factory CharacterProfile.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return CharacterProfile(
      id: serializer.fromJson<String>(json['id']),
      name: serializer.fromJson<String>(json['name']),
      role: serializer.fromJson<String>(json['role']),
      gender: serializer.fromJson<String>(json['gender']),
      aliases: serializer.fromJson<List<String>>(json['aliases']),
      tags: serializer.fromJson<List<String>>(json['tags']),
      biography: serializer.fromJson<String>(json['biography']),
      appearance: serializer.fromJson<String>(json['appearance']),
      description: serializer.fromJson<String>(json['description']),
      currentState: serializer.fromJson<String>(json['currentState']),
      avatarAssetId: serializer.fromJson<String?>(json['avatarAssetId']),
      photos: $CharacterProfilesTable.$converterphotosn.fromJson(
        serializer.fromJson<List<Object?>?>(json['photos']),
      ),
      voices: $CharacterProfilesTable.$convertervoicesn.fromJson(
        serializer.fromJson<List<Object?>?>(json['voices']),
      ),
      identity: serializer.fromJson<String>(json['identity']),
      age: serializer.fromJson<String>(json['age']),
      motivation: serializer.fromJson<String>(json['motivation']),
      arc: serializer.fromJson<String>(json['arc']),
      personality: serializer.fromJson<String>(json['personality']),
      behaviorTags: serializer.fromJson<List<CharacterBehaviorTag>>(
        json['behaviorTags'],
      ),
      firstAppearChapterId: serializer.fromJson<String?>(
        json['firstAppearChapterId'],
      ),
      sortOrder: serializer.fromJson<int>(json['sortOrder']),
