class ChapterData extends DataClass implements Insertable<ChapterData> {
  final String id;
  final String type;
  final String? parentId;
  final int siblingOrder;
  final String? title;
  final String outline;

  /// 写后总结，chronicler 发布后写入。outline 保持写前规划，不被覆盖。
  final String brief;
  final String content;
  final int wordCount;
  final String stat;

  /// 紧张度 1-10，chronicler 处理后估算。
  final int? tension;

  /// 情绪标签列表（2-4 字），chronicler 处理后提取。
  final List<String>? emotion;

  /// 章内事件序列 `[{title, summary, state_change}]`，chronicler 处理后提取。
  /// 与 brief 分工：brief 是整章散文总结，events 是可跨章聚合的结构化事件。
  final List<Map<String, dynamic>>? events;

  /// 作者对正文选区写下的批注 `[{id, start, end, quote, content, status, ...}]`。
  /// 与 events 分工：events 是 AI 提取的结构化事件，comments 是作者手写的笔记。
  final List<ChapterComment>? comments;
  final String embeddingSyncStatus;
  final DateTime? embeddingSyncedAt;
  final String? embeddingSyncModelId;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime deletedAt;
  const ChapterData({
    required this.id,
    required this.type,
    this.parentId,
    required this.siblingOrder,
    this.title,
    required this.outline,
    required this.brief,
    required this.content,
    required this.wordCount,
    required this.stat,
    this.tension,
    this.emotion,
    this.events,
    this.comments,
    required this.embeddingSyncStatus,
    this.embeddingSyncedAt,
    this.embeddingSyncModelId,
    required this.createdAt,
    required this.updatedAt,
    required this.deletedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['type'] = Variable<String>(type);
    if (!nullToAbsent || parentId != null) {
      map['parent_id'] = Variable<String>(parentId);
    }
    map['sibling_order'] = Variable<int>(siblingOrder);
    if (!nullToAbsent || title != null) {
      map['title'] = Variable<String>(title);
    }
    map['outline'] = Variable<String>(outline);
    map['brief'] = Variable<String>(brief);
    map['content'] = Variable<String>(content);
    map['word_count'] = Variable<int>(wordCount);
    map['stat'] = Variable<String>(stat);
    if (!nullToAbsent || tension != null) {
      map['tension'] = Variable<int>(tension);
    }
    if (!nullToAbsent || emotion != null) {
      map['emotion'] = Variable<String>(
        $ChaptersTable.$converteremotionn.toSql(emotion),
      );
    }
    if (!nullToAbsent || events != null) {
      map['events'] = Variable<String>(
        $ChaptersTable.$convertereventsn.toSql(events),
      );
    }
    if (!nullToAbsent || comments != null) {
      map['comments'] = Variable<String>(
        $ChaptersTable.$convertercommentsn.toSql(comments),
      );
    }
    map['embedding_sync_status'] = Variable<String>(embeddingSyncStatus);
    if (!nullToAbsent || embeddingSyncedAt != null) {
      map['embedding_synced_at'] = Variable<DateTime>(embeddingSyncedAt);
    }
    if (!nullToAbsent || embeddingSyncModelId != null) {
      map['embedding_sync_model_id'] = Variable<String>(embeddingSyncModelId);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['deleted_at'] = Variable<DateTime>(deletedAt);
    return map;
  }

  ChaptersCompanion toCompanion(bool nullToAbsent) {
    return ChaptersCompanion(
      id: Value(id),
      type: Value(type),
      parentId: parentId == null && nullToAbsent
          ? const Value.absent()
          : Value(parentId),
      siblingOrder: Value(siblingOrder),
      title: title == null && nullToAbsent
          ? const Value.absent()
          : Value(title),
      outline: Value(outline),
      brief: Value(brief),
      content: Value(content),
      wordCount: Value(wordCount),
      stat: Value(stat),
      tension: tension == null && nullToAbsent
          ? const Value.absent()
          : Value(tension),
      emotion: emotion == null && nullToAbsent
