          : Value(emotion),
      events: events == null && nullToAbsent
          ? const Value.absent()
          : Value(events),
      comments: comments == null && nullToAbsent
          ? const Value.absent()
          : Value(comments),
      embeddingSyncStatus: Value(embeddingSyncStatus),
      embeddingSyncedAt: embeddingSyncedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(embeddingSyncedAt),
      embeddingSyncModelId: embeddingSyncModelId == null && nullToAbsent
          ? const Value.absent()
          : Value(embeddingSyncModelId),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: Value(deletedAt),
    );
  }

