      events: serializer.fromJson<List<Map<String, dynamic>>?>(json['events']),
      comments: serializer.fromJson<List<ChapterComment>?>(json['comments']),
      embeddingSyncStatus: serializer.fromJson<String>(
        json['embeddingSyncStatus'],
      ),
      embeddingSyncedAt: serializer.fromJson<DateTime?>(
        json['embeddingSyncedAt'],
      ),
      embeddingSyncModelId: serializer.fromJson<String?>(
        json['embeddingSyncModelId'],
      ),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      deletedAt: serializer.fromJson<DateTime>(json['deletedAt']),
    );
  }
