class AiChatMessage extends DataClass implements Insertable<AiChatMessage> {
  final String id;
  final String sessionId;
  final String role;
  final String type;
  final String content;
  final List<AiMessageBlock>? blocks;
  final Map<String, dynamic>? metadata;

  /// 输入（prompt）token 数，含 cached tokens
  final int inputTokens;

  /// 输出（completion）token 数，含 reasoning tokens
  final int outputTokens;

  /// Prompt cache 命中（读取）token 数
  final int cacheReadTokens;

  /// Prompt cache 写入 token 数
  final int cacheWriteTokens;

  /// 推理/思考 token 数
  final int reasoningTokens;
  final int sequence;
  final DateTime createdAt;
  const AiChatMessage({
    required this.id,
    required this.sessionId,
    required this.role,
    required this.type,
    required this.content,
    this.blocks,
    this.metadata,
    required this.inputTokens,
    required this.outputTokens,
    required this.cacheReadTokens,
    required this.cacheWriteTokens,
    required this.reasoningTokens,
    required this.sequence,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['session_id'] = Variable<String>(sessionId);
    map['role'] = Variable<String>(role);
    map['type'] = Variable<String>(type);
    map['content'] = Variable<String>(content);
    if (!nullToAbsent || blocks != null) {
      map['blocks'] = Variable<String>(
        $AiChatMessagesTable.$converterblocksn.toSql(blocks),
      );
    }
    if (!nullToAbsent || metadata != null) {
      map['metadata'] = Variable<String>(
        $AiChatMessagesTable.$convertermetadatan.toSql(metadata),
      );
    }
    map['input_tokens'] = Variable<int>(inputTokens);
    map['output_tokens'] = Variable<int>(outputTokens);
    map['cache_read_tokens'] = Variable<int>(cacheReadTokens);
    map['cache_write_tokens'] = Variable<int>(cacheWriteTokens);
    map['reasoning_tokens'] = Variable<int>(reasoningTokens);
    map['sequence'] = Variable<int>(sequence);
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

  AiChatMessagesCompanion toCompanion(bool nullToAbsent) {
    return AiChatMessagesCompanion(
      id: Value(id),
      sessionId: Value(sessionId),
      role: Value(role),
      type: Value(type),
      content: Value(content),
      blocks: blocks == null && nullToAbsent
          ? const Value.absent()
          : Value(blocks),
      metadata: metadata == null && nullToAbsent
          ? const Value.absent()
          : Value(metadata),
      inputTokens: Value(inputTokens),
      outputTokens: Value(outputTokens),
      cacheReadTokens: Value(cacheReadTokens),
      cacheWriteTokens: Value(cacheWriteTokens),
