    return NovelMapsCompanion(
      id: Value(id),
      name: Value(name),
      description: Value(description),
      type: Value(type),
      locationId: locationId == null && nullToAbsent
          ? const Value.absent()
          : Value(locationId),
      width: Value(width),
      height: Value(height),
      settings: settings == null && nullToAbsent
