class CanvasNode extends DataClass implements Insertable<CanvasNode> {
  final String id;
  final String canvasId;
  final String type;

  /// 引用型必填:'character'/'chapter'/'foreshadowing'/'outline'/'location'/
  /// 'item'/'faction'/'skill'/'creature'/'document';便签型为 NULL。
  /// 制作画布:video/image → production_clip,staging → staging。
  /// media 通过 refType=asset/refId 读取资产；资产删除或文件缺失时展示错误，
  /// 不在节点保存文件路径或类型，也不回退到已删除资产的文件。
  final String? refType;

  /// 引用型必填:指向资源 id;便签型为 NULL。
  final String? refId;

  /// 引用型缓存资源标题(避免渲染时 join 资源表);便签型为便签标题。
  final String title;

  /// 便签正文；转为引用后保留但不展示，转回便签时复用。
  final String content;
  final double x;
  final double y;
  final double? width;
  final double? height;

  /// 纯视觉(颜色/形状/图标),非业务数据。
  final Map<String, dynamic>? style;
  final int zIndex;

  /// 分组内顺序；分镜组中即格位下标（行 × 列数 + 列）。
  final int sortOrder;

  /// 制作画布分组成员指向同画布的 [canvasNodeTypeGroup] 节点；NULL 表示不在分组中。
  final String? parentId;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime deletedAt;
  const CanvasNode({
    required this.id,
    required this.canvasId,
    required this.type,
    this.refType,
    this.refId,
    required this.title,
    required this.content,
    required this.x,
    required this.y,
    this.width,
    this.height,
    this.style,
    required this.zIndex,
    required this.sortOrder,
    this.parentId,
    required this.createdAt,
    required this.updatedAt,
    required this.deletedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['canvas_id'] = Variable<String>(canvasId);
    map['type'] = Variable<String>(type);
    if (!nullToAbsent || refType != null) {
      map['ref_type'] = Variable<String>(refType);
    }
    if (!nullToAbsent || refId != null) {
      map['ref_id'] = Variable<String>(refId);
    }
    map['title'] = Variable<String>(title);
    map['content'] = Variable<String>(content);
    map['x'] = Variable<double>(x);
    map['y'] = Variable<double>(y);
    if (!nullToAbsent || width != null) {
      map['width'] = Variable<double>(width);
    }
    if (!nullToAbsent || height != null) {
      map['height'] = Variable<double>(height);
    }
    if (!nullToAbsent || style != null) {
      map['style'] = Variable<String>(
        $CanvasNodesTable.$converterstylen.toSql(style),
      );
    }
    map['z_index'] = Variable<int>(zIndex);
    map['sort_order'] = Variable<int>(sortOrder);
    if (!nullToAbsent || parentId != null) {
      map['parent_id'] = Variable<String>(parentId);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['deleted_at'] = Variable<DateTime>(deletedAt);
    return map;
  }

  CanvasNodesCompanion toCompanion(bool nullToAbsent) {
    return CanvasNodesCompanion(
      id: Value(id),
      canvasId: Value(canvasId),
      type: Value(type),
      refType: refType == null && nullToAbsent
          ? const Value.absent()
          : Value(refType),
      refId: refId == null && nullToAbsent
          ? const Value.absent()
          : Value(refId),
      title: Value(title),
      content: Value(content),
      x: Value(x),
      y: Value(y),
      width: width == null && nullToAbsent
          ? const Value.absent()
          : Value(width),
      height: height == null && nullToAbsent
          ? const Value.absent()
          : Value(height),
      style: style == null && nullToAbsent
          ? const Value.absent()
          : Value(style),
      zIndex: Value(zIndex),
      sortOrder: Value(sortOrder),
      parentId: parentId == null && nullToAbsent
          ? const Value.absent()
          : Value(parentId),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: Value(deletedAt),
    );
  }

  factory CanvasNode.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return CanvasNode(
      id: serializer.fromJson<String>(json['id']),
      canvasId: serializer.fromJson<String>(json['canvasId']),
      type: serializer.fromJson<String>(json['type']),
      refType: serializer.fromJson<String?>(json['refType']),
      refId: serializer.fromJson<String?>(json['refId']),
      title: serializer.fromJson<String>(json['title']),
      content: serializer.fromJson<String>(json['content']),
      x: serializer.fromJson<double>(json['x']),
      y: serializer.fromJson<double>(json['y']),
      width: serializer.fromJson<double?>(json['width']),
      height: serializer.fromJson<double?>(json['height']),
      style: serializer.fromJson<Map<String, dynamic>?>(json['style']),
      zIndex: serializer.fromJson<int>(json['zIndex']),
      sortOrder: serializer.fromJson<int>(json['sortOrder']),
      parentId: serializer.fromJson<String?>(json['parentId']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      deletedAt: serializer.fromJson<DateTime>(json['deletedAt']),
    );
  }
